public extension EquipeMotion {
    /// Animation for a duration token; under Reduce Motion it is the short fade (`durationReduced`) and callers must also drop any travel (`travelReduced` = 0).
    static func animation(_ duration: TimeInterval, reduceMotion: Bool) -> Animation {
        EquipeMotion.easingStandard.animation(reduceMotion ? EquipeMotion.durationReduced : duration)
    }
}
